dashboard.definition:
{
    "title": "Network Assurance & Service Health",
    "description": "Network assurance: leading indicators vs. impact per service",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_signals": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_thousendeyes sourcetype=\"thousendeyes:json\" (thousandeyes.test.type=agent-to-agent OR (thousandeyes.agent.location=atlanta thousandeyes.test.type IN (\"bgp\", \"web-transaction\")))) OR (index=demo_msteams event_type=call_queue_stats queue_name=\"Support Hotline\") OR (index=demo_tomcat_logs host=berweb* status=504)\n| eval a2a=if('thousandeyes.test.type'=\"agent-to-agent\", 'metric_name:network.loss', null())\n| eval fra_loss=if('thousandeyes.target.agent.location'=\"frankfurt\", a2a, null()), ber_loss=if(like('thousandeyes.test.name', \"%Berlin%\") AND NOT like('thousandeyes.test.name', \"% to Frankfurt\"), a2a, null())\n| eval timeout=if(index=\"demo_tomcat_logs\", 1, null()), bgp=if('thousandeyes.test.type'=\"bgp\", 'metric_name:bgp.reachability', null()), b2b=if('thousandeyes.test.type'=\"web-transaction\", 'metric_name:web.transaction.completion', null())\n| bin _time span=1m\n| stats avg(fra_loss) as fra_loss avg(ber_loss) as ber_loss max(calls_waiting) as waiting count(timeout) as timeouts min(bgp) as bgp avg(b2b) as b2b by _time",
                "enableSmartSources": true,
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "Leading vs. impact (1 min)"
        },
        "ds_k_fra": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m avg(fra_loss) as \"Loss to DC Frankfurt\""
            }
        },
        "ds_k_wait": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m max(waiting) as \"Calls waiting\""
            }
        },
        "ds_k_ber": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m avg(ber_loss) as \"Berlin path loss\""
            }
        },
        "ds_k_504": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m sum(timeouts) as \"HTTP 504\""
            }
        },
        "ds_k_bgp": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m min(bgp) as \"BGP reachability\""
            }
        },
        "ds_k_b2b": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m avg(b2b) as \"B2B completion\""
            }
        },
        "ds_c_fra": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m avg(fra_loss) as \"Loss % to DC Frankfurt (leading)\" max(waiting) as \"Hotline calls waiting (impact)\""
            }
        },
        "ds_c_ber": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m avg(ber_loss) as \"Berlin DC path loss % (leading)\" sum(timeouts) as \"HTTP 504 Berlin (impact)\""
            }
        },
        "ds_c_atl": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_signals",
                "query": "| timechart span=1m min(bgp) as \"BGP reachability % (leading)\" avg(b2b) as \"B2B order completion % (impact)\""
            }
        },
        "ds_matrix": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\") OR (index=demo_cisco_meraki sourcetype=\"meraki:assurancealerts\" categoryType=connectivity) OR (index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type IN (\"agent-to-agent\", \"bgp\", \"http-server\")) OR (index=demo_msteams event_type=call_ended) OR (index=demo_mes ai_inspection_mode=*)\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval te_type='thousandeyes.test.type'\n| eval site=lower(coalesce(cat_site, mer_site, if(te_type=\"agent-to-agent\", mvappend('thousandeyes.agent.location', 'thousandeyes.target.agent.location'), 'thousandeyes.agent.location'), location))\n| eval dc_loss=if(te_type=\"agent-to-agent\", 'metric_name:network.loss', null()), bgp=if(te_type=\"bgp\", 'metric_name:bgp.reachability', null()), saas=if(te_type=\"http-server\", 'metric_name:http.server.request.availability', null()), ai=case(ai_inspection_mode=\"inline\", 100, isnotnull(ai_inspection_mode), 0)\n| stats avg(HealthScore) as campus count(eval(sourcetype=\"meraki:assurancealerts\")) as wan avg(dc_loss) as dc_loss latest(bgp) as bgp avg(saas) as saas avg(packet_loss_pct) as teams avg(ai) as ai by site\n| where site IN (\"atlanta\", \"berlin\", \"vienna\")\n| eval campus=round(campus, 1), dc_loss=round(dc_loss, 2), saas=round(saas, 1), teams=round(teams, 2), ai=round(ai, 0)\n| table site campus wan dc_loss bgp saas teams ai\n| rename site as Site campus as \"Campus health\" wan as \"WAN alerts\" dc_loss as \"DC path loss %\" bgp as \"BGP reachability %\" saas as \"SaaS availability %\" teams as \"Teams media loss %\" ai as \"AI inspection inline %\"",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-10m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "Service health matrix (live)"
        },
        "ds_paths": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=agent-to-agent\n| stats avg(metric_name:network.loss) as loss avg(metric_name:network.latency) as latency avg(metric_name:network.jitter) as jitter by thousandeyes.test.name\n| eval loss=round(loss, 2), latency=round(latency * 1000, 0), jitter=round(jitter, 1)\n| sort - loss\n| rename thousandeyes.test.name as Path loss as \"Loss %\" latency as \"Latency ms\" jitter as \"Jitter ms\"",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-5m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "DC paths (live)"
        },
        "ds_bgp": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=bgp\n| stats latest(bgp.prefix) as Prefix latest(bgp.as_path) as \"AS path\" latest(metric_name:bgp.reachability) as \"Reachability %\" sum(metric_name:bgp.path_changes.count) as \"Path changes\" sum(metric_name:bgp.updates.count) as Updates by thousandeyes.agent.location\n| rename thousandeyes.agent.location as \"Vantage point\"",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-10m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "BGP (live)"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
