        "viz_07": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_matrix"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 3,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Campus health": {
                        "rowBackgroundColors": "> table | seriesByName(\"Campus health\") | rangeValue(range_2)"
                    },
                    "WAN alerts": {
                        "rowBackgroundColors": "> table | seriesByName(\"WAN alerts\") | rangeValue(range_3)"
                    },
                    "DC path loss %": {
